CREATE TABLE `Ref_Document_Types` (
  `document_type_code` TEXT,
  `document_type_description` TEXT,
  PRIMARY KEY (`document_type_code`)
);

CREATE TABLE `Roles` (
  `role_code` TEXT,
  `role_description` TEXT,
  PRIMARY KEY (`role_code`)
);

CREATE TABLE `Addresses` (
  `address_id` NUMBER,
  `address_details` TEXT,
  PRIMARY KEY (`address_id`)
);

CREATE TABLE `Ref_Document_Status` (
  `document_status_code` TEXT,
  `document_status_description` TEXT,
  PRIMARY KEY (`document_status_code`)
);

CREATE TABLE `Ref_Shipping_Agents` (
  `shipping_agent_code` TEXT,
  `shipping_agent_name` TEXT,
  `shipping_agent_description` TEXT,
  PRIMARY KEY (`shipping_agent_code`)
);

CREATE TABLE `Documents` (
  `document_id` NUMBER,
  `document_status_code` TEXT REFERENCES `Ref_Document_Status`(`document_status_code`),
  `document_type_code` TEXT REFERENCES `Ref_Document_Types`(`document_type_code`),
  `shipping_agent_code` TEXT REFERENCES `Ref_Shipping_Agents`(`shipping_agent_code`),
  `receipt_date` TIME,
  `receipt_number` TEXT,
  `other_details` TEXT,
  PRIMARY KEY (`document_id`)
);

CREATE TABLE `Employees` (
  `employee_id` NUMBER,
  `role_code` TEXT REFERENCES `Roles`(`role_code`),
  `employee_name` TEXT,
  `other_details` TEXT,
  PRIMARY KEY (`employee_id`)
);

CREATE TABLE `Document_Drafts` (
  `document_id` NUMBER REFERENCES `Documents`(`document_id`),
  `draft_number` NUMBER,
  `draft_details` TEXT,
  PRIMARY KEY (`document_id`)
);

CREATE TABLE `Draft_Copies` (
  `document_id` NUMBER REFERENCES `Document_Drafts`(`document_id`),
  `draft_number` NUMBER REFERENCES `Document_Drafts`(`draft_number`),
  `copy_number` NUMBER,
  PRIMARY KEY (`document_id`)
);

CREATE TABLE `Circulation_History` (
  `document_id` NUMBER REFERENCES `Draft_Copies`(`document_id`),
  `draft_number` NUMBER REFERENCES `Draft_Copies`(`draft_number`),
  `copy_number` NUMBER REFERENCES `Draft_Copies`(`copy_number`),
  `employee_id` NUMBER REFERENCES `Employees`(`employee_id`),
  PRIMARY KEY (`document_id`)
);

CREATE TABLE `Documents_Mailed` (
  `document_id` NUMBER REFERENCES `Documents`(`document_id`),
  `mailed_to_address_id` NUMBER REFERENCES `Addresses`(`address_id`),
  `mailing_date` TIME,
  PRIMARY KEY (`document_id`)
);

